import {BUSINESS_DEFAULTS,businessValue} from './business-model.js?v=0.9.0';
const money=v=>v===null?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(v),signed=v=>v===null?'—':(v<0?'−':'+')+money(Math.abs(v));
const num=n=>Number(n.toFixed(1)).toLocaleString();
const field=(key,label,value,max=10000)=>`<div><label for="business-${key}">${label}</label><input id="business-${key}" name="${key}" type="number" inputmode="decimal" step="any" min="0" max="${max}" value="${value}" required></div>`;
function card(title,caption,body){return `<section class="card chart-card"><h3>${title}</h3><p class="chart-caption">${caption}</p>${body}</section>`;}
function netCards(v){const b=v.business;return `<div class="cost-headline"><div><span>Estimated DoorDash fees avoided</span><strong>${money(v.cost.orders?b.ddFees:null)}</strong><small>Gross commissions · before in-house expenses</small></div>${[['DoorDash',b.ddNet],['Uber Eats',b.uberNet]].map(([label,net])=>`<div class="${net!==null&&net<0?'cost-negative':''}"><span>Estimated net savings vs. ${label}</span><strong>${signed(net)}</strong><small>${net===null?'Complete timing and mileage needed':net>=0?'In-house advantage in this scenario':'Outsourcing advantage in this scenario'}</small></div>`).join('')}</div>`;}
function bridge(v){const c=v.cost,b=v.business,items=[['Platform charges avoided',c.dd],['Replacement kitchen labor if outsourcing',b.replacementCost],['Mileage paid in-house',-c.mileage],['Driver wages outsourcing would remove',-b.avoidableWages],['App cost in selected period',-b.assumptions.appCost]],max=Math.max(1,...items.map(x=>Math.abs(x[1])),Math.abs(b.ddNet||0));return `<div class="business-bridge">${[...items,['Estimated net savings',b.ddNet]].map(([label,value],i)=>`<div class="bridge-row ${i===5?'bridge-total':''}"><span>${label}</span><strong>${signed(value)}</strong><div><i style="width:${Math.abs(value||0)/max*100}%;background:${value<0?'#b47e35':'#275947'}"></i></div></div>`).join('')}</div><p class="muted">DoorDash example. Positive amounts favor in-house delivery; negative amounts reduce that advantage. Platform charges include selected equipment assumptions. Replacement labor is added only if you enter hours needed when the driver is absent.</p>`;}
function curve(v){const rows=v.business.cumulative,max=Math.max(1,...rows.flatMap(r=>[Math.abs(r.dd),Math.abs(r.uber)])),x=i=>50+(rows.length===1?245:490*i/(rows.length-1)),y=n=>125-n/max*85;return `<svg class="report-svg" viewBox="0 0 600 258" role="img" aria-label="Cumulative estimated net savings"><title>Cumulative estimated net savings, above zero favors in-house</title><line x1="50" x2="560" y1="125" y2="125" class="chart-zero"/>${[-1,0,1].map(n=>`<text x="42" y="${y(n*max)+4}" text-anchor="end" class="chart-axis">${n<0?'−':''}$${Math.round(Math.abs(n*max))}</text>`).join('')}${[['dd','#275947'],['uber','#628597']].map(([key,color])=>`<path d="${rows.map((r,i)=>`${i?'L':'M'}${x(i)},${y(r[key])}`).join(' ')}" fill="none" stroke="${color}" stroke-width="3" ${key==='uber'?'stroke-dasharray="7 5"':''}/>`).join('')}${rows.map((r,i)=>i===0||i===rows.length-1?`<text x="${x(i)}" y="245" text-anchor="middle" class="chart-axis">${r.date.slice(5)}</text>`:'').join('')}</svg><div class="chart-legend"><span><i style="background:#275947"></i>vs. DoorDash</span><span><i style="background:#628597"></i>vs. Uber Eats (dashed)</span></div><details class="chart-data"><summary>View savings by sample shift</summary><div class="table-wrap"><table><tr><th>Sample date</th><th>vs. DoorDash</th><th>vs. Uber Eats</th></tr>${rows.map(r=>`<tr><td>${r.date}</td><td>${signed(r.dd)}</td><td>${signed(r.uber)}</td></tr>`).join('')}</table></div></details>`;}
export function businessOverview(state,shifts,costInputs,raw=BUSINESS_DEFAULTS){const v=businessValue(state,shifts,costInputs,raw),b=v.business,a=b.assumptions,e=v.evidence,complete=v.cost.coverageComplete;return `<section class="business-intro"><p class="eyebrow">BUSINESS VALUE · DEMO SCENARIO</p><h2>Keep more of each delivery.</h2><p>See the fees in-house delivery can avoid, then subtract the expenses that really change. These are estimates from fictional shifts—not measured profit or guaranteed savings.</p></section>${netCards(v)}<section class="card business-staffing"><h2>What happens to the driver’s paid hours?</h2><p>The starting example assumes the driver stays on the same paid schedule to help inside the restaurant. This is an editable staffing assumption, not a verified payroll saving.</p><div class="actions business-presets">${[[0,'Same paid hours'],[50,'Half the delivery hours removed'],[100,'All delivery hours removed']].map(([pct,label])=>`<button type="button" data-business-role="${pct}" class="${a.avoidablePercent===pct?'primary':''}" aria-pressed="${a.avoidablePercent===pct}">${label}</button>`).join('')}</div><p class="business-scenario"><strong>${a.avoidablePercent}% of delivery wages would disappear if outsourced.</strong> ${money(b.avoidableWages)} is counted as avoidable pay; the rest is paid either way and cancels from this spending comparison.</p><details><summary>Customize staffing, replacement work & app price</summary><form id="business-form"><div class="form-grid">${field('avoidablePercent','Delivery wages outsourcing would eliminate (%)',a.avoidablePercent,100)}${field('replacementHours','Extra kitchen hours needed if outsourcing — entire selected period',a.replacementHours)}${field('replacementWage','Replacement kitchen wage ($ / hour)',a.replacementWage,500)}${field('appCost','App price assumption for selected period ($) — currently free',a.appCost,100000)}</div><p class="muted">Replacement hours mean extra paid hours, not tasks someone can finish within their existing schedule. Enter them once for this entire date range; review when changing dates. App price is only a what-if input and never charges you.</p><p class="error" id="business-error" role="alert"></p><button class="primary" type="submit">Update business scenario</button></form></details></section><div class="chart-grid business-charts">${card('Where the savings come from','Avoided charges minus the costs that change. Wages paid in both arrangements are not counted twice.',complete?bridge(v):'<p class="chart-empty">Net savings need complete delivery timing and mileage.</p>')}${card('Estimated savings over time','Above zero favors in-house; below zero favors outsourcing. Identical fee settings produce overlapping lines. Period replacement labor and app price are spread equally across the selected shifts.',complete?curve(v):'<p class="chart-empty">Select complete records to see the savings trend.</p>')}${card('Why staffing changes the result','Same orders, travel and fee assumptions; change only the share of delivery wages removed by outsourcing.',`<div class="staffing-results">${b.roles.map(r=>`<div><span>${r.percent}% of delivery wages removed</span><strong class="${r.dd<0?'negative-value':''}">${signed(r.dd)}</strong><small>vs. DoorDash</small></div>`).join('')}</div><p class="muted">Entered replacement labor and app price are held fixed. Negative results remain visible. Staffing changes—not a different set of orders—explain the difference.</p>`)}${card('Delivery work, grouped efficiently','Recorded fictional activity, not a claim of fuel savings or improvement caused by the app.',`<div class="business-evidence"><div><strong>${e.batchOrders}</strong><span>orders grouped into ${e.batchTrips} multi-order runs</span></div><div><strong>${e.groupedTrips}</strong><span>fewer departures than one separate run per grouped order</span></div><div><strong>${e.tasks}</strong><span>kitchen task check-offs recorded</span></div></div><p class="muted">Grouping does not prove how many miles or minutes were saved. Kitchen check-offs document work; no dollar value is added to savings.</p>`)}</div><section class="card business-app"><p class="eyebrow">THE APP’S VALUE · EVIDENCE TO BUILD</p><h2>What improves because of the app?</h2><p>Employing your own driver can avoid platform fees. The app’s separate contribution needs before-and-after evidence.</p><div class="business-evidence"><div><strong>${e.scheduled.total?`${e.scheduled.onTime} / ${e.scheduled.total}`:'Not recorded'}</strong><span>scheduled sample orders delivered by their requested time</span></div><div><strong>${e.coldOrders?`${e.coldConfirmed} / ${e.coldOrders}`:'Not recorded'}</strong><span>cold-item confirmations recorded; not an accuracy score</span></div><div><strong>Not measured</strong><span>actual order-entry time and change in forgotten items</span></div></div><p class="muted">Scheduled timing and check-offs describe sample activity. They do not establish improvement over the previous process. Missed-item incidents and before/after entry measurements are not yet collected.</p><details><summary>Illustrate possible order-entry time savings</summary><form id="entry-form"><label class="checkbox-label"><input type="checkbox" name="entryScenario" ${a.entryScenario?'checked':''}> Show an illustrative estimate, not measured app results</label><div class="form-grid">${field('beforeSeconds','Before app — seconds per order',a.beforeSeconds,3600)}${field('afterSeconds','With app — seconds per order',a.afterSeconds,3600)}</div><p class="error" id="entry-error" role="alert"></p><button type="submit">Calculate illustrative time difference</button></form></details>${b.entryMinutes===null?'':`<p class="business-scenario"><strong>${num(Math.abs(b.entryMinutes))} minutes ${b.entryMinutes>=0?'saved':'added'} in this illustration.</strong> ${v.cost.orders} sample orders × (${a.beforeSeconds} − ${a.afterSeconds}) seconds. Not measured, not a payroll saving, and not added to the financial totals.</p>`}</section><div class="hint"><strong>What this can establish:</strong> an estimated spending advantage under the selected assumptions. It does not establish net profit, new sales, service quality, or a universal advantage for all restaurants. One-time Uber setup is excluded from recurring savings; first-period estimated savings vs. Uber are ${signed(b.uberFirstPeriodNet)} with your entered setup assumption.</div>`;}
